/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: albumWith, observeHero, mount
 *   Constants: sample, longTitle, tone, track
 * Tests
 *   - tints the hero and main pane with the artwork tone, starting neutral while it samples
 *   - uses the neutral tone without sampling when the Album has no managed artwork
 *   - reveals the compact header only after the hero scrolls under it, and its Play launches the Album
 *   - keeps the compact header hidden where IntersectionObserver is unavailable
 * @end-catalog */

import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { act, cleanup, render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { MemoryRouter, Route, Routes } from 'react-router';

import { listenerCapabilitiesQueryKey } from '../../api/listenerCapabilities';
import { browserSessionQueryKey } from '../../api/session';
import { sampleArtworkTone } from '../../artwork/artworkTone';
import { neutralArtworkTone } from '../../artwork/useArtworkTone';
import { playerStore } from '../../player';
import { AlbumPage } from './AlbumPage';

vi.mock('../../artwork/artworkTone', () => ({ sampleArtworkTone: vi.fn() }));

const sample = vi.mocked(sampleArtworkTone);
const longTitle = 'Chiikawa the Movie: The Secret of Mermaid Island (Original Motion Picture Soundtrack)';
const tone = { hero: '#2f5f8a', pane: '#203f5c' };
const albumWith = (title: string, artworkUrl = '') => ({
  contentType: 'album', id: 'album-1', title, artworkUrl, artistNames: ['Artist'], releaseDate: null
});
const track = {
  contentType: 'audioTrack', id: 'track-1', title: 'Opening', artworkUrl: '', artistNames: ['Artist'],
  albumId: 'album-1', albumTitle: 'Album', duration: '3:00', mediaType: 'audio', streamUrl: '/content/mediaTrack/stream/track-1'
};

/** Captures the hero observer so tests can scroll the hero out from under the compact bar. */
const observeHero = () => {
  const observers: Array<{
    callback: IntersectionObserverCallback;
    options?: IntersectionObserverInit;
    targets: Element[];
    disconnected: boolean;
  }> = [];
  vi.stubGlobal('IntersectionObserver', class {
    record: (typeof observers)[number];
    constructor(callback: IntersectionObserverCallback, options?: IntersectionObserverInit) {
      this.record = { callback, options, targets: [], disconnected: false };
      observers.push(this.record);
    }
    observe(target: Element) { this.record.targets.push(target); }
    disconnect() { this.record.disconnected = true; }
  });
  const scrollHero = (top: number, isIntersecting: boolean) => act(() => {
    const observer = observers.at(-1)!;
    observer.callback([{
      isIntersecting,
      boundingClientRect: { top } as DOMRectReadOnly,
      rootBounds: { top: 64 } as DOMRectReadOnly
    } as IntersectionObserverEntry], {} as IntersectionObserver);
  });
  return { observers, scrollHero };
};

const mount = (album: ReturnType<typeof albumWith>) => {
  vi.stubGlobal('fetch', vi.fn(async () => new Response(JSON.stringify({ album, tracks: [track] }), {
    headers: { 'Content-Type': 'application/json' }
  })));
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  client.setQueryData(browserSessionQueryKey, null);
  client.setQueryData(listenerCapabilitiesQueryKey, { playlists: false });
  const main = document.createElement('main');
  main.id = 'main-content';
  document.body.append(main);
  const view = render(
    <QueryClientProvider client={client}>
      <MemoryRouter initialEntries={['/albums/album-1']}>
        <Routes><Route path="/albums/:albumId" element={<AlbumPage />} /></Routes>
      </MemoryRouter>
    </QueryClientProvider>,
    { container: main }
  );
  return { main, ...view };
};

afterEach(() => {
  cleanup();
  vi.unstubAllGlobals();
  document.body.innerHTML = '';
});

test.each([
  ['Night Geometry', undefined],
  ['Music for Quiet Rooms at Dawn', 'medium'],
  ['千と千尋の神隠し サウンドトラック', 'small'],
  [longTitle, 'xsmall']
])('scales the %j hero title by length and keeps the full title available', async (title, size) => {
  mount(albumWith(title));
  const heading = await screen.findByRole('heading', { level: 1, name: title });
  expect(heading).toHaveAttribute('title', title);
  if (size) expect(heading).toHaveAttribute('data-title-size', size);
  else expect(heading).not.toHaveAttribute('data-title-size');
});

test('tints the hero and main pane with the artwork tone, starting neutral while it samples', async () => {
  let finish!: (value: typeof tone) => void;
  sample.mockReturnValue(new Promise((resolve) => { finish = resolve; }));
  const { main, unmount } = mount(albumWith('Blue Hour', '/content/images/0000000000000000000000f1'));
  const hero = (await screen.findByRole('heading', { level: 1, name: 'Blue Hour' })).closest('header')!;

  expect(hero.style.getPropertyValue('--tone-color')).toBe(neutralArtworkTone.hero);
  expect(main.style.getPropertyValue('--tone-color')).toBe(neutralArtworkTone.pane);
  await waitFor(() => expect(sample).toHaveBeenCalledWith('/content/images/0000000000000000000000f1/v1/96.webp'));

  await act(async () => finish(tone));
  expect(hero.style.getPropertyValue('--tone-color')).toBe(tone.hero);
  expect(main.style.getPropertyValue('--tone-color')).toBe(tone.pane);

  unmount();
  expect(main.style.getPropertyValue('--tone-color')).toBe('');
});

test('uses the neutral tone without sampling when the Album has no managed artwork', async () => {
  const { main } = mount(albumWith('Unframed'));
  const hero = (await screen.findByRole('heading', { level: 1, name: 'Unframed' })).closest('header')!;
  expect(hero.style.getPropertyValue('--tone-color')).toBe(neutralArtworkTone.hero);
  expect(main.style.getPropertyValue('--tone-color')).toBe(neutralArtworkTone.pane);
  expect(sample).not.toHaveBeenCalled();
});

test('reveals the compact header only after the hero scrolls under it, and its Play launches the Album', async () => {
  const user = userEvent.setup();
  const launch = vi.spyOn(playerStore, 'launchAlbumQueue').mockResolvedValue();
  const { observers, scrollHero } = observeHero();
  const { main, unmount } = mount(albumWith(longTitle));
  const heading = await screen.findByRole('heading', { level: 1, name: longTitle });
  const compactPlay = { name: `Play ${longTitle}` };

  const observer = observers.at(-1)!;
  expect(observer.targets).toEqual([heading.closest('header')]);
  expect(observer.options?.root).toBe(main);
  expect(observer.options?.rootMargin).toMatch(/^-\d+px 0px 0px 0px$/);
  expect(screen.queryByRole('button', compactPlay)).not.toBeInTheDocument();

  // A hero below the fold is not "scrolled out".
  scrollHero(900, false);
  expect(screen.queryByRole('button', compactPlay)).not.toBeInTheDocument();

  scrollHero(-420, false);
  const play = screen.getByRole('button', compactPlay);
  expect(play.closest('[inert]')).toBeNull();
  await user.click(play);
  expect(launch).toHaveBeenCalledWith([expect.objectContaining({ id: track.id })], 0);
  // Only the hero heading names the page; the compact title is presentational.
  expect(screen.getAllByRole('heading', { level: 1 })).toHaveLength(1);

  scrollHero(-20, true);
  expect(screen.queryByRole('button', compactPlay)).not.toBeInTheDocument();
  expect(screen.getByText(longTitle, { selector: 'span' }).parentElement).toHaveAttribute('inert');

  unmount();
  expect(observer.disconnected).toBe(true);
});

test('keeps the compact header hidden where IntersectionObserver is unavailable', async () => {
  vi.stubGlobal('IntersectionObserver', undefined);
  mount(albumWith('Night Geometry'));
  await screen.findByRole('heading', { level: 1, name: 'Night Geometry' });
  expect(screen.getByRole('button', { name: 'Play' })).toBeInTheDocument();
  expect(screen.queryByRole('button', { name: 'Play Night Geometry' })).not.toBeInTheDocument();
});
